// Validates the packs and inlines them, with the runtime, into the canvas (poc/prototype/index.html)
// between the NEXUS-PACKS markers. The canvas is generated from the packs: do not edit that block by hand.
// Usage (Docker): docker run --rm -u "$(id -u):$(id -g)" -v "$PWD":/w -w /w node:22-slim node packs/build.mjs [--check]
// Usage: node packs/build.mjs          build and inline
//        node packs/build.mjs --check  fail if the canvas is out of date (used in CI and tests)
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
const rt = () => createRequire(import.meta.url)("./runtime.js");
const here = dirname(fileURLToPath(import.meta.url));
const canvas = join(here, "../poc/prototype/index.html");
export function loadPacks() {
  const files = ["core", "components", "services"].flatMap((d) => readdirSync(join(here, d)).filter((f) => f.endsWith(".json")).sort().map((f) => join(here, d, f)));
  const packs = files.map((f) => JSON.parse(readFileSync(f, "utf8")));
  const errs = [], ids = new Set();
  for (const p of packs) {
    for (const k of ["id", "version", "title", "owner", "layer", "schema", "applies_to"]) if (p[k] == null) errs.push(`${p.id || "?"}: missing ${k}`);
    if (ids.has(p.id)) errs.push(`${p.id}: duplicate id`); ids.add(p.id);
    if (!/^\d+\.\d+\.\d+$/.test(p.version || "")) errs.push(`${p.id}: version must be X.Y.Z`);
    const fids = new Set();
    for (const f of p.facts || []) {
      for (const k of ["id", "label", "kind", "unit", "source", "checked"]) if (f[k] == null) errs.push(`${p.id}.${f.id || "?"}: missing ${k}`);
      if (fids.has(f.id)) errs.push(`${p.id}.${f.id}: duplicate fact`); fids.add(f.id);
      if (!/^https:\/\/(docs\.aws\.amazon\.com|learn\.microsoft\.com|docs\.cloud\.google\.com|cloud\.google\.com)\//.test(f.source || "")) errs.push(`${p.id}.${f.id}: source must be an official documentation URL`);
      if (f.min != null && f.max != null && f.min > f.max) errs.push(`${p.id}.${f.id}: min > max`);
      if (f.default != null && f.max != null && f.kind !== "quota" && f.default > f.max) errs.push(`${p.id}.${f.id}: default above max`);
    }
    for (const r of p.rules || []) for (const id of r.facts || []) if (!fids.has(id)) errs.push(`${p.id}: rule ${r.id} cites unknown fact ${id}`);
    if (p.sp) {
      for (const k of ["name", "level", "status", "providers", "covers", "not_covered"]) if (p.sp[k] == null) errs.push(`${p.id}: sp.${k} missing`);
      if (!p.policy || typeof p.policy !== "object") errs.push(`${p.id}: policy missing`);
      if (!Array.isArray(p.integration) || !p.integration.length) errs.push(`${p.id}: integration missing`);
      const impl = new Set(rt().spChecks());
      for (const r of p.rules || []) {
        for (const k of ["rationale", "basis", "refs", "fix"]) if (r[k] == null || (Array.isArray(r[k]) && !r[k].length)) errs.push(`${p.id}: rule ${r.id} has no ${k}`);
        if (!impl.has(r.check)) errs.push(`${p.id}: rule ${r.id} has no check in packs/runtime.js`);
      }
    }
  }
  if (errs.length) throw new Error("Invalid packs:\n  " + errs.join("\n  "));
  return packs;
}
export function block() {
  const packs = loadPacks();
  const bundle = { built: createHash("sha256").update(JSON.stringify(packs)).digest("hex").slice(0, 12), lock: Object.fromEntries(packs.map((p) => [p.id, p.version])), packs };
  const json = JSON.stringify(bundle).replace(/</g, "\\u003c");
  const rt = readFileSync(join(here, "runtime.js"), "utf8");
  return `<!--NEXUS-PACKS:BEGIN generated by packs/build.mjs from packs/; do not edit-->\n<script id="nexusPacks" type="application/json">${json}</script>\n<script>\n${rt}</script>\n<!--NEXUS-PACKS:END-->`;
}
const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const html = readFileSync(canvas, "utf8"), re = /<!--NEXUS-PACKS:BEGIN[\s\S]*?<!--NEXUS-PACKS:END-->/;
  if (!re.test(html)) { console.error("packs: markers not found in the canvas"); process.exit(1); }
  const next = html.replace(re, () => block());
  if (process.argv.includes("--check")) {
    if (next !== html) { console.error("packs: the canvas is out of date. Run: docker run --rm -u \"$(id -u):$(id -g)\" -v \"$PWD\":/w -w /w node:22-slim node packs/build.mjs"); process.exit(1); }
    console.log("packs: canvas is up to date");
  } else { writeFileSync(canvas, next); console.log(`packs: ${loadPacks().length} packs inlined into poc/prototype/index.html`); }
}
